3	const wrapAnsi16 = (offset = 0) => code => `\u001B[${code + offset}m`;
4	
5	const wrapAnsi256 = (offset = 0) => code => `\u001B[${38 + offset};5;${code}m`;
6	
7	const wrapAnsi16m = (offset = 0) => (red, green, blue) => `\u001B[${38 + offset};2;${red};${green};${blue}m`;
